// 原Talk/真实约定产生接触，位置移动与时钟不会刷新记忆；此门未代完整World及GUI。
#define main original_appointment_contact_fixture_not_executed
#include "personal_appointment_test.cpp"
#undef main
#include "resident/domains/interaction/known_contacts/known_contact_location_view.hpp"
int main(){try{
    AppointmentFixture f;FamilyDeathOriginRead none=[](const StableId&)->Outcome<std::optional<FamilyDeathOrigin>>{return {true,std::nullopt,{}};};
    AppointmentContactHistory history{f.interaction,f.ic,f.appointments,f.appointment_state,none};KnownContactLocationAccess read{f.common,*f.shared,&history,nullptr};
    auto empty=read_known_contact_locations(read,"player");require(empty.ok&&empty.value.rows.empty(),"current co-location alone is not a persistent contact source");auto accepted=f.accept();f.leave();
    auto first=read_known_contact_location(read,"player","sender");require(first.ok&&first.value&&first.value->source_fact_id==accepted&&first.value->place_id=="market"&&first.value->observed_tick==10&&first.value->learned_tick==10,"only actual accepted meeting creates historical direct knowledge");
    auto reverse=read_known_contact_location(read,"sender","player");require(reverse.ok&&reverse.value&&reverse.value->source_fact_id==accepted,"both actual participants know this original contact");auto outsider=read_known_contact_locations(read,"stranger");require(outsider.ok&&outsider.value.rows.empty(),"unrelated observer cannot see other people's promises");
    auto absent=read_known_contact_location(read,"player","not_an_actor"),unseen=read_known_contact_location(read,"player","recipient");require(absent.ok&&unseen.ok&&!absent.value&&!unseen.value,"unknown ID and real but unobserved actor are equally unknown");
    f.shared->places.insert("far_camp",{"far_camp","other_town",{}});f.common.state().actors.find("sender")->location=SettlementLocation{"other_town","far_camp"};f.common.state().identity.tick=12;
    const auto before_common=encode_common_state(f.common.state()),before_history=encode_personal_appointments(f.appointment_state);auto retained=read_known_contact_location(read,"player","sender");require(retained.ok&&retained.value&&retained.value->place_id=="market"&&retained.value->observed_tick==10,"far current position and future appointment window do not update last seen location");require(compare_boundary(before_common,encode_common_state(f.common.state())).exact()&&compare_boundary(before_history,encode_personal_appointments(f.appointment_state)).exact(),"query changes no time, source, money, position or appointment state");
    KnownContactLocationAccess unavailable{f.common,*f.shared,nullptr,nullptr};require(read_known_contact_locations(unavailable,"player").value.rows.empty(),"no selected source does not fall back to world location scan");require(!read_known_contact_locations(read,"player",-1).ok&&!read_known_contact_locations(read,"player",0,51).ok,"finite reader rejects invalid cursors and oversize requests");
    f.common.state().actors.find("sender")->location=SettlementLocation{"town","market"};f.talk("cancel");auto q=preview_personal_appointment_cancel(f.common,f.interaction,f.ic,f.access,f.appointments,f.appointment_state,"player",{accepted});require(q.ok,"real later contact for mutual cancellation");auto cancelled=cancel_personal_appointment_in_candidate(f.common,f.interaction,f.ic,f.access,f.appointments,f.appointment_state,q.value);require(cancelled.ok,"actual cancellation contact");f.leave();auto latest=read_known_contact_location(read,"player","sender");require(latest.ok&&latest.value&&latest.value->source_fact_id==cancelled.value&&latest.value->observed_tick==12,"latest actual fact replaces older contact without changing original records");
    SceneCatalog scene;ScenePlaceDefinition place;place.id="market";place.settlement_id="town";place.name_key="market_name";scene.places.insert(place.id,place);f.shared->texts.insert("market_name","原集市");f.shared->texts.insert("sender_name","原会面人");f.shared->actor_names.insert("sender",{"sender_name",{}, {}});auto page=query_known_contact_locations(read,scene);require(page.ok&&page.value.find("rows")->as<BoundaryValue::Array>()->size()==1,"finite current-observer page uses exact selected actor and place presentation");const auto& displayed=page.value.find("rows")->as<BoundaryValue::Array>()->front();require(*displayed.find("place_name")->as<StableId>()=="原集市"&&!*displayed.find("current_location_confirmed")->as<bool>()&&*displayed.find("observed_tick")->as<Integer>()==12&&!displayed.find("actions"),"page labels only original location and provides no direct movement or remote action");
    const auto original=f.appointment_state;f.appointment_state.by_participant["stranger"].push_back(accepted);require(!read_known_contact_locations(read,"player").ok,"forged participant index must not enter known-location projection");f.appointment_state=original;
    AppointmentFixture failed;AppointmentContactHistory fh{failed.interaction,failed.ic,failed.appointments,failed.appointment_state,none};KnownContactLocationAccess fr{failed.common,*failed.shared,&fh,nullptr};auto id=failed.accept();failed.leave();++failed.common.state().identity.tick;failed.talk("meet");auto action=failed.begin(id);const auto start=failed.appointment_state.started.order().back();failed.shared->places.insert("now_elsewhere",{"now_elsewhere","town",{}});failed.common.state().actors.find("sender")->location=SettlementLocation{"town","now_elsewhere"};auto finish=failed.complete(action);require(!finish.success,"real movement causes original meeting interruption");auto old=read_known_contact_location(fr,"player","sender");require(old.ok&&old.value&&old.value->source_fact_id==start&&old.value->observed_tick==11,"failed finish does not falsely place absent participant at the later completion time");
    std::cout<<"KNOWN_CONTACT_SOURCE: real appointment history, bounded last-seen knowledge; World unrun\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
